import pandas as pd


def latest_nps(preds: pd.DataFrame, scores: pd.DataFrame) -> pd.DataFrame:
    """Most recent NPS strictly before each prediction date."""
    joined = preds.merge(scores, on="customer")
    joined = joined.sort_values("scored_at").groupby(["customer", "as_of"]).tail(1)
    return joined[["customer", "as_of", "nps"]].sort_values(["customer", "as_of"]).reset_index(drop=True)
